+        printf("AOF %s is empty\n", filepath);
+    } else if (ret == AOF_CHECK_TIMESTAMP_TRUNCATED) {
+        printf("Successfully truncated AOF %s to timestamp %ld\n",
+            filepath, to_timestamp);
